local CoronationCushionMaker = {}
local PRODUCTS = {
    simple_velvet_cushion = { name = "Preprost žamčast vzglavnik", silkCost = 2, woolCost = 1, threadCost = 1, time = 3, cost = 50, beauty = 22, prestige = 3, happiness = 1, description = "Preprost žamčast vzglavnik za slovesnosti." },
    tasseled_silk_cushion = { name = "Resasta svilena vzglavnik", silkCost = 3, woolCost = 1, threadCost = 1, time = 6, cost = 150, beauty = 38, prestige = 8, happiness = 2, description = "Resasta svilena vzglavnik za trgovce." },
    silver_trimmed_cushion = { name = "Srebrnoobrobljeni vzglavnik", silkCost = 3, silverCost = 1, woolCost = 1, threadCost = 1, time = 9, cost = 380, beauty = 52, prestige = 16, happiness = 2, description = "Srebrnoobrobljeni vzglavnik za plemiče." },
    gold_embroidered_cushion = { name = "Zlato vezani vzglavnik", silkCost = 4, goldCost = 1, silverCost = 1, woolCost = 1, threadCost = 1, time = 13, cost = 900, beauty = 68, prestige = 28, happiness = 3, description = "Zlato vezani vzglavnik za visoke plemiče." },
    jewel_cornered_cushion = { name = "Draguljakotni vzglavnik", silkCost = 4, goldCost = 2, silverCost = 1, woolCost = 1, threadCost = 1, jewelCost = 1, time = 17, cost = 2000, beauty = 80, prestige = 42, happiness = 5, description = "Vzglavnik z draguljnimi koti za visoko plemstvo." },
    royal_grand_coronation_cushion = { name = "Kraljevski veliki kronanski vzglavnik", silkCost = 6, goldCost = 3, silverCost = 2, woolCost = 2, threadCost = 2, jewelCost = 2, pearlCost = 2, time = 24, cost = 4500, beauty = 95, prestige = 70, happiness = 12, description = "Veliki kraljevski kronanski vzglavnik z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    cushion_workshop = { name = "Vzglavniška delavnica", cost = { gold = 240, wood = 100, stone = 100, silk = 6, wool = 6 }, upkeep = 5, qualityBonus = 5 },
    upholstery_loft = { name = "Tapetniška podstrešje", cost = { gold = 880, wood = 240, stone = 240, silver = 6, thread = 6 }, upkeep = 20, qualityBonus = 18 },
    master_upholsterer_atelier = { name = "Mojstrski tapetniški atelje", cost = { gold = 2500, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_upholstery_palace = { name = "Kraljevska tapetniška palača", cost = { gold = 10500, wood = 580, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
CoronationCushionMaker.silkStock = 14; CoronationCushionMaker.woolStock = 12; CoronationCushionMaker.threadStock = 12; CoronationCushionMaker.silverStock = 6; CoronationCushionMaker.goldStock = 6; CoronationCushionMaker.jewelStock = 4; CoronationCushionMaker.pearlStock = 4
CoronationCushionMaker.productStock = {}; CoronationCushionMaker.buildings = {}; CoronationCushionMaker.maker = nil; CoronationCushionMaker.activeMaking = {}; CoronationCushionMaker.totalProducts = 0; CoronationCushionMaker.dayTimer = 0
function CoronationCushionMaker.init() CoronationCushionMaker.silkStock=14; CoronationCushionMaker.woolStock=12; CoronationCushionMaker.threadStock=12; CoronationCushionMaker.silverStock=6; CoronationCushionMaker.goldStock=6; CoronationCushionMaker.jewelStock=4; CoronationCushionMaker.pearlStock=4; CoronationCushionMaker.productStock={}; CoronationCushionMaker.buildings={}; CoronationCushionMaker.maker=nil; CoronationCushionMaker.activeMaking={}; CoronationCushionMaker.totalProducts=0; CoronationCushionMaker.dayTimer=0; print("[CoronationCushionMaker] Royal Coronation Cushion Maker System initialized (6 products, 4 buildings)") end
function CoronationCushionMaker.hireMaker(n,s) s=s or math.random(55,90); local c=520+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CoronationCushionMaker.maker={name=n or ("Vzglavnikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vzglavnikar najet: %s (spretnost: %d)",CoronationCushionMaker.maker.name,s),"success") end; return true end
function CoronationCushionMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CoronationCushionMaker.build(id) local ok,e=CoronationCushionMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CoronationCushionMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CoronationCushionMaker.getQualityBonus() local b=0; for _,bd in ipairs(CoronationCushionMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CoronationCushionMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.silkCost and CoronationCushionMaker.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.woolCost and CoronationCushionMaker.woolStock<(d.woolCost or 0) then return false,"Premalo volne" end; if d.threadCost and CoronationCushionMaker.threadStock<(d.threadCost or 0) then return false,"Premalo niti" end; if d.silverCost and CoronationCushionMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CoronationCushionMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CoronationCushionMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CoronationCushionMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CoronationCushionMaker.buildings==0 then return false,"Potrebna vzglavniška delavnica" end; if not CoronationCushionMaker.maker then return false,"Potreben vzglavnikar" end; return true end
function CoronationCushionMaker.make(pt,qty) qty=qty or 1; local ok,e=CoronationCushionMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.silkCost then CoronationCushionMaker.silkStock=CoronationCushionMaker.silkStock-d.silkCost*qty end; if d.woolCost then CoronationCushionMaker.woolStock=CoronationCushionMaker.woolStock-d.woolCost*qty end; if d.threadCost then CoronationCushionMaker.threadStock=CoronationCushionMaker.threadStock-d.threadCost*qty end; if d.silverCost then CoronationCushionMaker.silverStock=CoronationCushionMaker.silverStock-d.silverCost*qty end; if d.goldCost then CoronationCushionMaker.goldStock=CoronationCushionMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CoronationCushionMaker.jewelStock=CoronationCushionMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CoronationCushionMaker.pearlStock=CoronationCushionMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CoronationCushionMaker.maker then t=math.max(1,t-math.floor(CoronationCushionMaker.maker.skill/12)) end; table.insert(CoronationCushionMaker.activeMaking,{id="cushion_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Šivanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CoronationCushionMaker.completeMaking(m) local q=1.0+(CoronationCushionMaker.getQualityBonus()/100); if CoronationCushionMaker.maker then q=q+(CoronationCushionMaker.maker.skill/140) end; q=math.min(2.5,q); CoronationCushionMaker.productStock[m.productType]=(CoronationCushionMaker.productStock[m.productType] or 0)+m.quantity; CoronationCushionMaker.totalProducts=CoronationCushionMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CoronationCushionMaker.maker then CoronationCushionMaker.maker.itemsMade=CoronationCushionMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CoronationCushionMaker.maker.skill=math.min(100,CoronationCushionMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vzglavnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"cushion.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function CoronationCushionMaker.update(dt) if not _G.state then return end; CoronationCushionMaker.dayTimer=CoronationCushionMaker.dayTimer+dt; if CoronationCushionMaker.dayTimer>=30 then CoronationCushionMaker.dayTimer=0; for i=#CoronationCushionMaker.activeMaking,1,-1 do local m=CoronationCushionMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CoronationCushionMaker.completeMaking(m); table.remove(CoronationCushionMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CoronationCushionMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CoronationCushionMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CoronationCushionMaker.getStats() return {silkStock=CoronationCushionMaker.silkStock,woolStock=CoronationCushionMaker.woolStock,threadStock=CoronationCushionMaker.threadStock,silverStock=CoronationCushionMaker.silverStock,goldStock=CoronationCushionMaker.goldStock,jewelStock=CoronationCushionMaker.jewelStock,pearlStock=CoronationCushionMaker.pearlStock,productStock=CoronationCushionMaker.productStock,numBuildings=#CoronationCushionMaker.buildings,hasMaker=CoronationCushionMaker.maker~=nil,makerName=CoronationCushionMaker.maker and CoronationCushionMaker.maker.name or "—",makerSkill=CoronationCushionMaker.maker and CoronationCushionMaker.maker.skill or 0,activeMaking=#CoronationCushionMaker.activeMaking,totalProducts=CoronationCushionMaker.totalProducts} end
return CoronationCushionMaker
